def get_median(nums):
    """Returns the median of a list of numbers."""
    nums.sort()
    n = len(nums)
    if n % 2 == 0:
        return (nums[n // 2 - 1] + nums[n // 2]) / 2
    else:
        return nums[n // 2]

def find_kth_smallest(nums, k):
    """Finds the k-th smallest element in a list."""
    return get_median(nums[:k])
