def solve(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    sorted_nums = sorted(counts.keys())

    for i in range(len(sorted_nums)):
        if k <= counts[sorted_nums[i]]:
            return sorted_nums[i]
        k -= counts[sorted_nums[i]]

    return sorted_nums[-1]
