def binary_search_min(arr):
    """
    Finds the minimum element in a sorted array using binary search.
    """
    low = 0
    high = len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    return arr[low]

def binary_search_max(arr):
    """
    Finds the maximum element in a sorted array using binary search.
    """
    low = 0
    high = len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] < arr[high]:
            low = mid + 1
        else:
            high = mid
    return arr[low]

def find_min_max(arr):
    """
    Finds the minimum and maximum values in an unsorted array.
    """
    min_val = arr[0]
    max_val = arr[0]
    for num in arr:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num
    return min_val, max_val

def partition(arr, low, high, x):
    """
    Partitions the array around a pivot x.
    """
    i = low
    for j in range(low, high):
        if arr[j] <= x:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
    arr[i], arr[high] = arr[high], arr[i]
    return i

def quickselect(arr, low, high, k):
    """
    Finds the k-th smallest element in an array using quickselect.
    """
    if low == high:
        return arr[low]
    pivot_index = partition(arr, low, high, arr[high])
    rank = pivot_index - low + 1
    if k == rank:
        return arr[pivot_index]
    elif k < rank:
        return quickselect(arr, low, pivot_index - 1, k)
    else:
        return quickselect(arr, pivot_index + 1, high, k - rank)

def solve(nums, k):
    """
    Finds the k-th smallest element in an array.
    """
    return quickselect(nums, 0, len(nums) - 1, k)
