import sys

def solve(text, prefix):
    if not text or not prefix:
        return 0 if prefix == "" else -1

    if len(prefix) > len(text):
        return -1

    if prefix == text[:len(prefix)]:
        if len(prefix) == len(text):
            return 0
        else:
            return solve(text[1:], prefix)
    else:
        return -1

def solve_recursive(text, prefix):
    if not text or not prefix:
        return 0 if prefix == "" else -1

    if len(prefix) > len(text):
        return -1

    if prefix == text[:len(prefix)]:
        if len(prefix) == len(text):
            return 0
        else:
            return solve_recursive(text[1:], prefix)
    else:
        return -1

def solve_wrapper(text, prefix):
    if not text or not prefix:
        return 0 if prefix == "" else -1

    if len(prefix) > len(text):
        return -1

    if prefix == text[:len(prefix)]:
        if len(prefix) == len(text):
            return 0
        else:
            return solve_wrapper(text[1:], prefix)
    else:
        return -1

def solve(text, prefix):
  return solve_wrapper(text, prefix)
