def find_root(parent, i):
    if parent[i] == i:
        return i
    return find_root(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find_root(parent, x)
    yroot = find_root(parent, y)
    if xroot != yroot:
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

def dfs(node, parent, visited):
    visited[node] = True
    for neighbor in adj[node]:
        if not visited[neighbor]:
            dfs(neighbor, parent, visited)

def solve(n, edges):
    parent = list(range(n))
    rank = [0] * n
    adj = [[] for _ in range(n)]

    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for u, v in edges:
        union(parent, rank, u, v)

    num_components = 0
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            dfs(i, parent, visited)
            num_components += 1

    return num_components
