def get_neighbors(graph, node):
    """Returns a list of neighbors for a given node in a graph."""
    return graph.get(node, [])

def remove_visited(graph, node, visited):
    """Removes a node from the graph and visited set."""
    if node in graph:
        del graph[node]
    visited.add(node)

def dfs(graph, node, visited):
    """Performs depth-first search to explore a connected component."""
    visited.add(node)
    for neighbor in get_neighbors(graph, node):
        if neighbor not in visited:
            dfs(graph, neighbor, visited)

def get_connected_components(graph):
    """Finds and returns the number of connected components in a graph."""
    visited = set()
    count = 0
    for node in graph:
        if node not in visited:
            dfs(graph, node, visited)
            count += 1
    return count

def solve(n, edges):
