def solution(n: int, times: list[int], parties: list[list[int]]) -> int:
    """
    Given the number of people, the times each party takes to set up, and a list of parties,
    return the minimum time needed to set up all the parties.
    """
    graph = {}
    for time, party in zip(times, parties):
        if time not in graph:
            graph[time] = []
        graph[time].append(party)

    visited = set()
    count = 0

    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)

    for time in graph:
        if time not in visited:
            dfs(time)
            count += 1

    return count
