def solve():
    nums = list(range(1000))
    target = 500

    def find_target_index(nums, target):
        left, right = 0, len(nums) - 1
        index = -1

        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                index = mid
                right = mid - 1  # Continue searching on the left side
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return index

    index1 = find_target_index(nums, target)
    index2 = find_target_index(nums, target + 1)

    if index1 != -1:
         if index2 == -1:
                return (index1, index1)
         else:
                return (index1, index2)
    else:
        return (index2, index2)

