    Given a sorted array of integers, find the first and last occurrence of the target value.
    """
    if not nums:
        return [-1, -1]

    first = -1
    last = -1

    # Find the first occurrence
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            first = mid
            right = mid - 1  # Continue searching on the left side
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    # Find the last occurrence
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            last = mid
            left = mid + 1  # Continue searching on the right side
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return [first, last]
