def solve(nums, target):
    """
    Finds the indices of a target value in a sorted array.

    Args:
        nums: A sorted array of integers.
        target: The target value to search for.

    Returns:
        A tuple containing the indices of the target value in the array.
        If the target value is not found, returns (-1, -1).
    """
    left = 0
    right = len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return (mid, mid)
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return (-1, -1)
