def solve(nums, target):
    """
    Checks if a target value exists in a list of numbers and returns the indices of the first and last occurrences.

    Args:
        nums: A list of numbers.
        target: The target value to search for.

    Returns:
        A tuple containing the indices of the first and last occurrences of the target value.
    """
    n = len(nums)
    first_occurrence = -1
    last_occurrence = -1

    for i in range(n):
        if nums[i] == target:
            if first_occurrence == -1:
                first_occurrence = i
            last_occurrence = i

    if first_occurrence != -1:
        return (first_occurrence, last_occurrence)
    else:
        return (first_occurrence, last_occurrence)
