def solve(nums):
  """
  Finds the length of the longest increasing subsequence in a list of numbers.

  Args:
    nums: A list of numbers.

  Returns:
    The length of the longest increasing subsequence.
  """
  if not nums:
    return 0

  dp = [1] * len(nums)

  for i in range(1, len(nums)):
    for j in range(i):
      if nums[i] > nums[j]:
        dp[i] = max(dp[i], dp[j] + 1)

  return max(dp)
```

