def solve(nums):
    """
    Finds the number of ways to choose elements from nums such that the chosen elements
    form a subsequence with elements in strictly increasing order.
    """
    n = len(nums)
    dp = [1] * n  # dp[i] stores the length of the longest increasing subsequence ending at index i

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
```

