def avoid_wall(grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()

    def dfs(row, col):
        if (row, col) in visited:
            return 0

        if row < 0 or row >= rows or col < 0 or col >= cols or grid[row][col] == 1:
            return 0

        visited.add((row, col))

        return 1 + max(dfs(row + 1, col), dfs(row - 1, col), dfs(row, col + 1), dfs(row, col - 1))

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                visited = set()
                dfs(r, c)

    return len(visited)
