def avoid_wall(grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()

    def dfs(row, col):
        if (row, col) in visited or not (0 <= row < rows and 0 <= col < cols) or grid[row][col] == '#':
            return 0

        visited.add((row, col))

        down = dfs(row + 1, col)
        right = dfs(row, col + 1)

        return 1 + max(down, right)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '#':
                visited = set()
                dfs(r, c)

    return len(visited) - sum(1 for r in range(rows) for c in range(cols) if grid[r][c] == '#')
