def longest_increasing_subsequence_recursive(nums):
    if not nums:
        return 0

    def _lis(nums, index, prev):
        if index == len(nums):
            return 0

        # Option 1: Exclude the current element
        exclude = _lis(nums, index + 1, prev)

        # Option 2: Include the current element if it's greater than the previous one
        include = 0
        if prev is None or nums[index] > prev:
            include = 1 + _lis(nums, index + 1, nums[index])

        return max(exclude, include)

    return _lis(nums, 0, None)

